package com.forgeide.core.runtime;
import com.forgeide.core.sandbox.*;import com.forgeide.core.util.*;import org.junit.Test;import java.util.*;import java.util.concurrent.*;import static org.junit.Assert.*;
public class RuntimeTest{
 private JavaScriptRuntime.Result run(String source,StringBuilder output,SandboxPolicy policy,CancellationToken c){return new JavaScriptRuntime().run(source,"main.js",List.of("dev"),Map.of("NAME","Forge"),"hello\nworld",policy,c,output::append,null);}
 @Test public void executesRealJavaScript(){StringBuilder out=new StringBuilder();assertEquals(0,run("function add(a,b){return a+b;} console.log(add(2,3)); print(arguments[0], env.NAME, readLine());",out,SandboxPolicy.safeDefault(),new CancellationToken()).exitCode);assertEquals("5\ndev Forge hello\n",out.toString());}
 @Test public void javaAndFilesystemAreNotExposed(){StringBuilder out=new StringBuilder();assertEquals(0,run("print(typeof java,typeof Packages,typeof Java,typeof require,typeof process,typeof console.getClass);",out,SandboxPolicy.safeDefault(),new CancellationToken()).exitCode);assertEquals("undefined undefined undefined undefined undefined undefined\n",out.toString());}
 @Test(timeout=4000) public void infiniteLoopHitsDeadline(){SandboxPolicy p=new SandboxPolicy(100,1024,SandboxPolicy.safeDefault().required);assertEquals(124,run("while(true){}",new StringBuilder(),p,new CancellationToken()).exitCode);}
 @Test public void outputLimitAndSyntaxErrors(){SandboxPolicy p=new SandboxPolicy(1000,1024,SandboxPolicy.safeDefault().required);StringBuilder out=new StringBuilder();assertEquals(124,run("while(true)print('0123456789');",out,p,new CancellationToken()).exitCode);assertTrue(out.length()<=1024);assertEquals(1,run("let = ;",new StringBuilder(),p,new CancellationToken()).exitCode);}
 @Test public void unsupportedHardLimitsFailClosed(){Set<SandboxPolicy.Restriction> required=EnumSet.copyOf(SandboxPolicy.safeDefault().required);required.add(SandboxPolicy.Restriction.HARD_MEMORY_LIMIT);try{new SandboxPolicy(1000,1024,required).requireSupported(SandboxPolicy.safeDefault().required);fail();}catch(SecurityException expected){}}
 @Test(timeout=5000) public void cancellationStopsRunningProgram()throws Exception{CancellationToken c=new CancellationToken();ExecutorService e=Executors.newSingleThreadExecutor();try{Future<JavaScriptRuntime.Result> f=e.submit(()->run("while(true){}",new StringBuilder(),SandboxPolicy.safeDefault(),c));c.cancel();assertEquals(130,f.get(3,TimeUnit.SECONDS).exitCode);}finally{e.shutdownNow();}}
 @Test(timeout=5000) public void debuggerStepsAndInspectsRealActivationScopes()throws Exception{BlockingQueue<String> events=new LinkedBlockingQueue<>();ScriptDebugger debugger=new ScriptDebugger(Map.of(3,"x === 2"),events::add);ExecutorService executor=Executors.newSingleThreadExecutor();try{Future<JavaScriptRuntime.Result> f=executor.submit(()->new JavaScriptRuntime().run("var x = 1;\nx = 2;\nprint(x);","debug.js",List.of(),Map.of(),"",SandboxPolicy.safeDefault(),new CancellationToken(),s->{},debugger));assertNotNull(events.poll(2,TimeUnit.SECONDS));debugger.control("continue","");String stopped=events.poll(2,TimeUnit.SECONDS);assertNotNull(stopped);assertTrue(stopped.contains("breakpoint"));assertTrue(stopped.contains("variables"));debugger.control("evaluate","x + 3");String watch=events.poll(2,TimeUnit.SECONDS);assertTrue(watch.contains("\"value\":\"5\""));events.poll(2,TimeUnit.SECONDS);debugger.control("continue","");assertEquals(0,f.get(2,TimeUnit.SECONDS).exitCode);}finally{debugger.control("continue","");executor.shutdownNow();}}
}
